function validate([nums, queries]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 10000) return 'nums needs 1 to 10000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each value of nums is a whole number from -10000 to 10000.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 10000) return 'queries needs 1 to 10000 entries.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [val, index].';
    const [val, index] = query;
    if (!Number.isInteger(val) || val < -10000 || val > 10000) return 'Each val is a whole number from -10000 to 10000.';
    if (!Number.isInteger(index) || index < 0 || index >= nums.length) return 'Each index must point inside nums.';
  }
  return null;
}

