function sumEvenAfterQueries(nums, queries) {
  let evenSum = 0;
  for (const value of nums) {
    if (value % 2 === 0) {
      evenSum += value;
    }
  }

  const answer = [];
  for (const [val, index] of queries) {
    if (nums[index] % 2 === 0) {
      evenSum -= nums[index];
    }
    nums[index] += val;
    if (nums[index] % 2 === 0) {
      evenSum += nums[index];
    }
    answer.push(evenSum);
  }
  return answer;
}

