function sumEvenAfterQueries(nums, queries) {
  // Apply each query to a copy, then add up the even values from scratch.
  const values = nums.slice();
  return queries.map(([val, index]) => {
    values[index] = values[index] + val;
    return values.filter(v => (v & 1) === 0).reduce((total, v) => total + v, 0);
  });
}

