function generate(rand, size) {
  const between = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? 2000 : between(1, 6);
  const q = size === 'large' ? 2000 : between(1, 6);
  const span = size === 'large' ? 10000 : 6;
  const nums = Array.from({ length: n }, () => between(-span, span));
  const queries = Array.from({ length: q }, () => [between(-span, span), between(0, n - 1)]);
  return [nums, queries];
}
